export function buildComment(diff, findings) {
    const changedCriteria = collectChangedCriteria(diff.diffs);
    const errors = findings.filter((finding) => finding.severity === "error");
    const warnings = findings.filter((finding) => finding.severity === "warning");
    const state = errors.length > 0 ? "fail" : warnings.length > 0 ? "review" : "pass";
    return [
        "## AuraOne Rubric Review",
        "",
        `**Decision:** ${decisionLabel(state)}`,
        "",
        "| Evidence | Result |",
        "| --- | ---: |",
        `| Rubric files | ${diff.files.length} |`,
        `| Changed criteria | ${changedCriteria.length} |`,
        `| Blocking findings | ${errors.length} |`,
        `| Review findings | ${warnings.length} |`,
        "",
        "### Changed Criteria",
        "",
        ...(changedCriteria.length
            ? changedCriteria.map((criterionId) => `- \`${escapeInlineCode(criterionId)}\``)
            : ["No criterion-level changes detected."]),
        "",
        "### File Changes",
        "",
        "| File | Added | Removed | Changed |",
        "| --- | ---: | ---: | ---: |",
        ...diff.diffs.map((item) => `| \`${escapeInlineCode(item.file)}\` | ${item.added.length} | ${item.removed.length} | ${item.changed.length} |`),
        "",
        "### Findings",
        "",
        ...(findings.length
            ? findings.map((finding) => `- **${finding.severity === "error" ? "Blocking" : "Review"}** \`${escapeInlineCode(finding.rule)}\` in \`${escapeInlineCode(finding.file ?? "rubric")}${escapeInlineCode(finding.path ?? "")}\`: ${escapeMarkdown(finding.message)}`)
            : ["No lint findings."]),
        "",
        "### Next action",
        "",
        nextAction(state),
        "",
        "[Rubric specification](https://github.com/auraoneai/rubric-spec)",
        "",
        "Generated by AuraOne Rubric PR Bot 0.2.0. Rubric content is processed through the installed GitHub App.",
    ].join("\n");
}
function collectChangedCriteria(diffs) {
    const ids = new Set();
    for (const diff of diffs) {
        for (const id of diff.added)
            ids.add(id);
        for (const id of diff.removed)
            ids.add(id);
        for (const item of diff.changed) {
            if (item.criterion_id)
                ids.add(item.criterion_id);
        }
    }
    return [...ids].sort();
}
function decisionLabel(state) {
    return { pass: "Passed", review: "Review recommended", fail: "Action required" }[state];
}
function nextAction(state) {
    return {
        pass: "No blocking action is required. Confirm the rubric diff matches the intended evaluation contract.",
        review: "Review the lint findings and add examples, anchors, or clearer criterion language before merging.",
        fail: "Resolve every blocking finding, push the corrected rubric, and rerun the check.",
    }[state];
}
export function escapeMarkdown(value) {
    return value
        .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, "")
        .replace(/([\\`*_[\]{}()#+\-.!|>])/g, "\\$1");
}
function escapeInlineCode(value) {
    return value.replace(/`/g, "\\`").replace(/[\r\n]/g, " ");
}
